import os
from typing import Any, Dict, List, Optional

from google.cloud import monitoring_v3


def query_metric_data(
    project_id: str,
    metric_type: str,
    resource_type: Optional[str] = None,
    resource_labels: Optional[Dict[str, str]] = None,
    metric_labels: Optional[Dict[str, str]] = None,
    minutes_back: int = 60,
) -> List[Dict[str, Any]]:
    """
    Query Google Cloud Monitoring time series data filtered by resource labels/dimensions.

    Requires:
      - google-cloud-monitoring
      - Application Default Credentials or service account credentials
      - Google Cloud project ID
    """
    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    end_time = monitoring_v3.TimeInterval()
    end_time.end_time.GetCurrentTime()

    import datetime

    start_dt = datetime.datetime.utcnow() - datetime.timedelta(minutes=minutes_back)
    end_dt = datetime.datetime.utcnow()
    interval = monitoring_v3.TimeInterval(
        {
            "end_time": {"seconds": int(end_dt.timestamp())},
            "start_time": {"seconds": int(start_dt.timestamp())},
        }
    )

    filter_parts = [f'metric.type = "{metric_type}"']

    if resource_type:
        filter_parts.append(f'resource.type = "{resource_type}"')

    if resource_labels:
        for key, value in resource_labels.items():
            filter_parts.append(f'resource.labels.{key} = "{value}"')

    if metric_labels:
        for key, value in metric_labels.items():
            filter_parts.append(f'metric.labels.{key} = "{value}"')

    filter_str = " AND ".join(filter_parts)

    results: List[Dict[str, Any]] = []
    for series in client.list_time_series(
        request={
            "name": project_name,
            "filter": filter_str,
            "interval": interval,
            "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
        }
    ):
        points = []
        for point in series.points:
            value = point.value
            if value.double_value is not None:
                extracted_value: Any = value.double_value
            elif value.int64_value is not None:
                extracted_value = value.int64_value
            elif value.bool_value is not None:
                extracted_value = value.bool_value
            elif value.string_value is not None:
                extracted_value = value.string_value
            elif value.distribution_value is not None:
                extracted_value = {
                    "count": value.distribution_value.count,
                    "mean": value.distribution_value.mean,
                    "sum_of_squared_deviation": value.distribution_value.sum_of_squared_deviation,
                    "bucket_counts": list(value.distribution_value.bucket_counts),
                }
            else:
                extracted_value = None

            points.append(
                {
                    "interval": {
                        "start_time": point.interval.start_time.ToDatetime().isoformat()
                        if point.interval.start_time.seconds or point.interval.start_time.nanos
                        else None,
                        "end_time": point.interval.end_time.ToDatetime().isoformat()
                        if point.interval.end_time.seconds or point.interval.end_time.nanos
                        else None,
                    },
                    "value": extracted_value,
                }
            )

        results.append(
            {
                "metric_type": series.metric.type,
                "resource_type": series.resource.type,
                "resource_labels": dict(series.resource.labels),
                "metric_labels": dict(series.metric.labels),
                "points": points,
            }
        )

    return results


if __name__ == "__main__":
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT", "")
    if not project_id:
        raise RuntimeError("GOOGLE_CLOUD_PROJECT environment variable is required")

    metric_type = os.environ.get(
        "METRIC_TYPE",
        "compute.googleapis.com/instance/cpu/utilization",
    )
    resource_type = os.environ.get("RESOURCE_TYPE", "gce_instance")

    data = query_metric_data(
        project_id=project_id,
        metric_type=metric_type,
        resource_type=resource_type,
        resource_labels={"instance_id": os.environ.get("INSTANCE_ID", "")}
        if os.environ.get("INSTANCE_ID")
        else None,
        minutes_back=int(os.environ.get("MINUTES_BACK", "60")),
    )

    print(data)
